  it('validates a function-valued tool against the schema returned for that call, not a cached one', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let requiredField = 'location';
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {[requiredField]: {type: 'string'}}, required: [requiredField]},
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const first = await registry.execute('get_weather', {location: 'Paris'});
    requiredField = 'city';
    const second = await registry.execute('get_weather', {location: 'Paris'});

    expect({first, second: second.result.includes('city'), executorCalls}).toEqual({
      first: {result: 'sunny'},
      second: true,
      executorCalls: 1,
    });
  });
});
'''
